161		}
162	
163		if rep.ItemsAtClose {
164			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
165			if len(rep.CloseItems) == 0 {
