174			}
175		} else {
176			if rep.HistoryIncomplete {
177				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
178			} else {
179				b.WriteString("\n事项：\n")
180			}
181			if len(rep.Items) == 0 {
182				b.WriteString("  （无）\n")
183			}
184			for _, it := range rep.Items {
185				b.WriteString(indentLines(FormatItem(it), "  "))
186			}
187		}
188	
189		b.WriteString("\n交班对象：\n")
190		if rep.Outgoing == nil {
191			b.WriteString("  （尚未发起交接）\n")
192		} else {
